"use strict";(self.webpackChunkbed_mega_textbook=self.webpackChunkbed_mega_textbook||[]).push([[9332],{5654(e,t,n){n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>h,default:()=>u,frontMatter:()=>r,metadata:()=>i,toc:()=>d});const i=JSON.parse('{"id":"semester-1/efmp-302/unit-05/unit-teacher-notes","title":"Unit 5 teacher notes","description":"Teaching notes for EFMP-302 Unit 5: sequencing across two weeks, handling a unit that describes hard conditions, the misconceptions that recur, and practical work.","source":"@site/docs/semester-1/efmp-302/unit-05/unit-teacher-notes.mdx","sourceDirName":"semester-1/efmp-302/unit-05","slug":"/semester-1/efmp-302/unit-05/unit-teacher-notes","permalink":"/semester-1/efmp-302/unit-05/unit-teacher-notes","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Unit 5 teacher notes","description":"Teaching notes for EFMP-302 Unit 5: sequencing across two weeks, handling a unit that describes hard conditions, the misconceptions that recur, and practical work.","course_code":"EFMP-302","unit_no":5,"clo_refs":["SLO:EFMP-302-5-1","SLO:EFMP-302-5-2"],"blooms_summary":"Teaching guidance only; no assessment items. Supports delivery across the Week 12 to Week 13 block.","est_reading_minutes":10,"translation_status":"draft"},"sidebar":"textbook","previous":{"title":"Unit 5 assessment","permalink":"/semester-1/efmp-302/unit-05/unit-assessment"},"next":{"title":"Sustaining Professionalism through Continuous Learning","permalink":"/semester-1/efmp-302/unit-06/"}}');var s=n(4848),a=n(8453),o=n(6606);const r={title:"Unit 5 teacher notes",description:"Teaching notes for EFMP-302 Unit 5: sequencing across two weeks, handling a unit that describes hard conditions, the misconceptions that recur, and practical work.",course_code:"EFMP-302",unit_no:5,clo_refs:["SLO:EFMP-302-5-1","SLO:EFMP-302-5-2"],blooms_summary:"Teaching guidance only; no assessment items. Supports delivery across the Week 12 to Week 13 block.",est_reading_minutes:10,translation_status:"draft"},h="Unit 5 teacher notes",c={},d=[{value:"The thing to get right in this unit",id:"the-thing-to-get-right-in-this-unit",level:2},{value:"Sequencing across the two-week block",id:"sequencing-across-the-two-week-block",level:2},{value:"The misconceptions that recur",id:"the-misconceptions-that-recur",level:2},{value:"Handling what this unit surfaces about the profession",id:"handling-what-this-unit-surfaces-about-the-profession",level:2},{value:"Practical work",id:"practical-work",level:2},{value:"Marking the unit assessment",id:"marking-the-unit-assessment",level:2}];function l(e){const t={h1:"h1",h2:"h2",header:"header",p:"p",strong:"strong",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(o.A,{}),"\n",(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"unit-5-teacher-notes",children:"Unit 5 teacher notes"})}),"\n",(0,s.jsx)(t.h2,{id:"the-thing-to-get-right-in-this-unit",children:"The thing to get right in this unit"}),"\n",(0,s.jsx)(t.p,{children:"This unit describes conditions that are genuinely difficult and, in several respects, not the\ntrainee's fault. Taught badly it produces either despair or cynicism, and cynicism in a\npre-service cohort is expensive: it arrives before they have taught anything, and it is the\nburnout dimension Topic 5.1 warns about, acquired second-hand."}),"\n",(0,s.jsx)(t.p,{children:"Two things prevent that."}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Reach Topic 5.4."})," Do not let the block run out with the difficulties described and the response\nuntaught. If you are short of time, compress Topic 5.2, not 5.4. A unit that stops after three\ntopics is worse than not teaching the unit at all."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Do not soften the description to protect morale."})," Trainees who are told that good technique\novercomes sixty-two pupils will discover otherwise in their first term and will then distrust\neverything else the course told them. The unit's own answer is better: the conditions are real,\nsome of them are not yours to fix, and there is still a short honest list of what is."]}),"\n",(0,s.jsx)(t.h2,{id:"sequencing-across-the-two-week-block",children:"Sequencing across the two-week block"}),"\n",(0,s.jsx)(t.p,{children:"Four topics over two weeks: 5.1 and 5.2 in Week 12, 5.3 and 5.4 in Week 13."}),"\n",(0,s.jsx)(t.p,{children:"Topic 5.1 is the longest in the course and carries five sub-topics. Give it two sessions if you\ncan, splitting after burnout and before the multilingual and multi-grade material."}),"\n",(0,s.jsx)(t.h2,{id:"the-misconceptions-that-recur",children:"The misconceptions that recur"}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:'"Burnout is just being very tired."'})," Correct this early and precisely, because the three\ndimensions do real work later. The most useful moment is the cynicism point: ask the class whether\nthey have met a teacher who advised them not to bother with a weak class, and let them reinterpret\nthat memory."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:'"The home language is the problem."'})," In some cohorts this is a firmly held position with\ninstitutional backing, and trainees may have been taught it. Argue it on cognitive load rather\nthan on rights, at least first; the rights argument lands better once the practical one is\naccepted."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:'"Integrating technology means using it in every lesson."'})," Trainees who have seen technology used\nas display will recognise the correction quickly."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:'"A teacher\'s status is fixed and nothing I do affects it."'}),' The status and recognition\ndistinction is the repair. Do not let it collapse into "be respected instead of paid properly",\nwhich is a different and much worse claim.']}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:'"The answer to difficult conditions is resilience."'})," The most important of the five, and the one\nmost likely to be reinforced elsewhere in a trainee's experience. Topic 5.4 names it directly."]}),"\n",(0,s.jsx)(t.h2,{id:"handling-what-this-unit-surfaces-about-the-profession",children:"Handling what this unit surfaces about the profession"}),"\n",(0,s.jsx)(t.p,{children:"Two predictable moments."}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Some trainees will say they chose teaching because nothing else was available."})," Topic 3.2 said\nthis is common and should not be met with exhortation. In this unit it may surface more sharply,\nbecause the conditions are being described honestly for the first time. The useful response is\nthat attitude is a stance rather than a feeling, and that this unit's final topic is about what\nremains available regardless of how anyone arrived."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Some trainees will be angry"}),", and the anger is frequently justified. Do not manage it away.\nDirect it: Unit 1's professional associations and Topic 5.4's second region, what you can influence, are where collective\npressure belongs, and a cohort that leaves knowing the difference between what to endure, what to\nchange and what to organise about has understood the unit."]}),"\n",(0,s.jsx)(t.h2,{id:"practical-work",children:"Practical work"}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Shadow and itemise (Week 12)."})," The Topic 5.1 task. Reliable and often the most affecting thing\nin the unit: trainees consistently find that uncounted work exceeds timetabled work. Ask for the\nratio rather than the detail in the debrief, and collect the ratios on the board. The distribution\nmakes the point better than any individual account."]}),"\n",(0,s.jsx)(t.p,{children:'Brief trainees that this is not an audit of their host teacher. The framing is "what does this job\nactually consist of", and a trainee who presents it otherwise will damage a placement.'}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Three people, one question (Week 12)."})," The Topic 5.2 task. If parent access is difficult in\nyour setting, two respondents are enough; do not let the task be dropped because the third is\nunavailable."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Judge one technology use (Week 13)."}),' The Topic 5.3 task. Many practicum schools will have\nalmost no technology, and "there is none" is a legitimate finding. Redirect those trainees to a\nphotocopied internet resource, which every school has and which raises the accuracy and alignment\nquestion.']}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Place it and change it (Week 13)."})," The Topic 5.4 task, and the one to protect if time is short.\nRequire the change to be makeable without permission, and check that requirement when you read the\nhalf-pages. The commonest failure is a plan that depends on the head agreeing to something."]}),"\n",(0,s.jsx)(t.h2,{id:"marking-the-unit-assessment",children:"Marking the unit assessment"}),"\n",(0,s.jsx)(t.p,{children:"The bank is on the unit assessment page with model answers and analytic rubrics."}),"\n",(0,s.jsx)(t.p,{children:"ERQ 5 is the integrative item, and its Diagnosis criterion is deliberately the hardest thing in\nthe bank. The remark about group work admits two defensible readings, and the unit teaches both:\nTopic 5.1's cynicism dimension, and Topic 5.4's accurate judgement about the third region being\nused to excuse inaction in the first. Mr Bilal is the worked case of the second, and topic-04\nsays plainly that he \"is not wrong about the numbers\"."}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Do not award the Strong band for naming cynicism alone, and do not withhold it from a candidate\nwho argues for the Topic 5.4 reading."})," Award it for distinguishing the two and arguing from the\ntext which the evidence supports. Telling an exhausted judgement apart from an accurate one is\nthe discrimination this unit exists to teach; a candidate who reaches for the first label is\ndoing to the described teacher exactly what the unit warns against."]}),"\n",(0,s.jsx)(t.p,{children:"Two marking cautions specific to this unit. First, RRQ 2 asks where each burnout source was\nconducted; that is deliberate, and a candidate who cites the studies without their scope should\nlose the mark, because this unit is partly about citation discipline. Second, ERQ 4 and ERQ 5 both\ninvite an answer that is really a complaint about the system. A complaint may be accurate and it is\nnot an answer; the rubrics cap it."})]})}function u(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(l,{...e})}):l(e)}},6606(e,t,n){n.d(t,{A:()=>s});n(6540);var i=n(4848);function s(e){var t=e.label,n=void 0===t?"Print / Save as PDF":t;return(0,i.jsxs)("button",{type:"button",className:"print-handout print-hidden","aria-label":"Print or save this handout as a PDF",onClick:function(){return"undefined"!=typeof window&&window.print()},children:[(0,i.jsx)("span",{"aria-hidden":"true",children:"\ud83d\udda8 "}),n]})}},8453(e,t,n){n.d(t,{R:()=>o,x:()=>r});var i=n(6540);const s={},a=i.createContext(s);function o(e){const t=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),i.createElement(a.Provider,{value:t},e.children)}}}]);